    public CGameCtnCollection() : this(GameVersion.Unspecified)
    {
    }

    public CGameCtnCollection(GameVersion gameVersion)
    {
        if (gameVersion == GameVersion.TM2020)
        {
            squareSize = 32f;
            squareHeight = 8f;
        }

        isEditable = true;
        waterTop = -1000f;
        waterBottom = -1000f;
        cameraMinHeight = -1000f;
        shadowSoftSizeInWorld = 1f;
        colorVertexMax = 1f;
